class AnimationEngine{constructor(){this.systems=[],this.lastTime=performance.now(),this.running=!1}register(i){i&&"function"==typeof i.update&&this.systems.push(i)}start(){this.running||(this.running=!0,requestAnimationFrame(this.loop.bind(this)))}loop(i){const t=(i-this.lastTime)/1e3;this.lastTime=i,this.systems.forEach(i=>{i.update&&i.update(t)}),requestAnimationFrame(this.loop.bind(this))}}window.AnimationEngine=new AnimationEngine;